H.background();
const cx = H.W * 0.5, cy = H.H * 0.54, R = Math.min(H.W, H.H) * 0.32;
const r = Math.max(0.2, P.r), th0 = P.theta * Math.PI / 180, n = Math.max(1, Math.round(P.n));
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 1.5 });
H.line(cx - R - 14, cy, cx + R + 14, cy, { color: H.colors.axis, width: 1 });
H.line(cx, cy - R - 14, cx, cy + R + 14, { color: H.colors.axis, width: 1 });
const sweep = (t * 0.5) % 1;
for (let k = 1; k <= n; k++) {
  const ang = k * th0;
  const rho = Math.pow(r, k);
  const reach = Math.min(1, rho);
  const px = cx + R * reach * Math.cos(ang), py = cy - R * reach * Math.sin(ang);
  H.line(cx, cy, px, py, { color: k === n ? H.colors.accent2 : H.colors.accent, width: k === n ? 3 : 1.5 });
  H.circle(px, py, k === n ? 6 : 4, { fill: k === n ? H.colors.warn : H.colors.accent });
}
const an = th0 + sweep * th0;
const rn = Math.min(1, Math.pow(r, 1 + sweep));
H.circle(cx + R * rn * Math.cos(an), cy - R * rn * Math.sin(an), 5 + Math.sin(t * 3), { fill: H.colors.good });
const finalAng = n * th0, finalR = Math.pow(r, n);
H.text("De Moivre: (r·cis θ)^n = r^n·cis(nθ)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("r = " + r.toFixed(2) + "   θ = " + P.theta.toFixed(0) + "°   n = " + n, 24, 52, { color: H.colors.sub, size: 13 });
H.text("z^n: modulus = " + finalR.toFixed(2) + "   angle = " + ((finalAng * 180 / Math.PI) % 360).toFixed(0) + "°", 24, 72, { color: H.colors.good, size: 13 });
H.legend([{ label: "z^n", color: H.colors.warn }, { label: "powers z^k", color: H.colors.accent }], H.W - 170, 28);
